# frozen_string_literal: true

# Repositories are defined with the class keyword so constants like `Users` resolve through LowData.const_missing.
class PostsData < LowData
  def nest_one = Posts[:title] + Users[:username]
  def nest_many = Users[:username] + Posts[:title]
  def nest_chain = Users[:username] + Posts[:title] + Comments[:body]
  def nest_chain_reordered = Users[:username] + Comments[:body] + Posts[:title]
  def nest_up = Comments[:body] + Posts[:title] + Users[:username]
  def nest_siblings = Posts[:title] + Comments[:body] + Likes[:id]
  def nest_all_columns = Posts[] + Users[:username]
  def nest_then_left = Users[:username] + Posts[:title] < Comments[:body]
  def nest_after_join = (Users[:username] & Posts[:title]) + Comments[:body]
  def nest_multiple_paths = Users[:username] + Posts[:title] + Likes[:id]
  def nest_unlinked = Users[:username] + Tags[:name]
  def nest_many_keys = Reviews[:rating] + Users[:username]
  def nest_self = Users[:username] + Users[:id]
  def nest_inverted = Table[:title] + Users[:username]
  def bracket_one = Posts[:title, Users[:username]]
  def bracket_many = Users[:username, Posts[:title]]
  def bracket_deep = Users[:username, Posts[:title, Likes[:id]]]
  def grouped = Users[:username] + (Posts[:title] + Likes[:id])
  def bracket_in_chain = Posts[:title, Comments[:body]] + Users[:username]
  def chain_in_bracket = Users[:username, Posts[:title] + Comments[:body]]
  def named_one = Reviews[:rating, author: Users[:username], editor: Users[:username]]
  def named_many = Users[:username, written: Posts[:title]]
  def named_unmatched = Reviews[:rating, writer: Users[:username]]
  def duplicate_keys = Users[:username, Posts[:title], Posts[:id]]
  def bracket_in_join = Users[:username, Posts[:title]] & Comments[:body]
  def filter_range = Posts[:title, views: 100..]
  def filter_upper = Posts[:title, views: ...100]
  def filter_in = Posts[:title, title: %w[Hello Orphan]]
  def filter_nil = Posts[:title, user_id: nil]
  def filter_joined = Users[:username] & Posts[:title, views: 100..]
  def filter_nested = Users[:username, Posts[:title, views: 100..]]
  def filter_subject = Users[:username, Posts[:title], username: 'alice']
  def explicit_posts = (Users[:username] > Posts[:title]) < Comments[:body]
  def full = Users[:username] <=> Posts[:title]
  def inner = Users[:username] & Posts[:title]
  def left = Users[:username] < Posts[:title]
  def right = Users[:username] > Posts[:title]
  def all_columns = Users[] & Posts[]
  def chained = Users[:username] & Posts[:title] & Comments[:body]
  def parenthesized = (Users[:username] < Posts[:title]) & Comments[:body]
  def nested = Users[:username] < Posts[:title] & Comments[:body]
  def unrelated = Users[:username] & Tags[:name]
  def ambiguous = Users[:username] & Reviews[:rating]
  def self_join = Users[:username] & Users[:id]
  def value = Users[:username] & :posts
  def type = Users[:username] & String
  def inverted = Table[:username, :title, :body]
  def inverted_order = Table[:title, :username]
  def inverted_unrelated = Table[:name]
  def inverted_missing = Table[:missing]
  def inverted_join = Table[:title] & Users[:username]
end
